#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/go/tasks/code-lint-gomod.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Fail when a go.mod or a go.sum is not tidy"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="lint every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="accepted for the code:lint contract"
# USAGE flag "--fix" help="run go mod tidy in each selected module"
# USAGE arg "[files]" var=#true help="the files to lint; a .go file, a go.mod or a go.sum selects its module; the default is the uncommitted files"
# FILES include="*.go go.mod go.sum"

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Shipped with the go tool. Without go, the task does not apply and prints
# nothing.
if not helpers.has_tool("go"):
  sys.exit(0)
os.chdir(os.environ["MISE_PROJECT_ROOT"])

# code:lint passes its flags and files to each code:lint:* task. The list
# comes from gate_files (the # FILES header above). An empty list: nothing
# to do.
args = [f"--{flag}" for flag in ("all", "debug", "fix") if os.environ.get(f"usage_{flag}") == "true"]
listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
try:
  if os.path.getsize(listing) == 0:
    sys.exit(0)

  # A file of the list selects the module of its nearest go.mod: a new import in
  # a Go file can make go.mod untidy. No module: nothing to do.
  with open(listing, encoding="utf-8", errors="surrogateescape") as f:
    files = f.read().split("\n")[:-1]
  modules = []
  for file in files:
    folder = os.path.dirname(file) or "."
    while not os.path.isfile(f"{folder}/go.mod") and folder not in (".", "/"):
      folder = os.path.dirname(folder) or "."
    if not os.path.isfile(f"{folder}/go.mod"):
      continue
    if folder not in modules:
      modules.append(folder)
  if not modules:
    sys.exit(0)

  helpers.print_header("Checking the Go modules with go mod tidy ...")
  for folder in modules:
    helpers.print_subheader(f"Checking the module in {folder} ...")
    if os.environ.get("usage_fix") == "true":
      result = helpers.tool("go", "mod", "tidy", cwd=folder)
    else:
      # -diff prints the changes that go mod tidy makes, and exits 1 when there
      # are changes. It writes no file.
      result = helpers.tool("go", "mod", "tidy", "-diff", cwd=folder)
    if result.returncode != 0:
      sys.exit(result.returncode)
finally:
  os.remove(listing)
